{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Where each photo and video was taken.",
  "mark": {
    "type": "circle",
    "size": 80
  },
  "encoding": {
    "longitude": {
      "field": "gps_lon",
      "type": "quantitative"
    },
    "latitude": {
      "field": "gps_lat",
      "type": "quantitative"
    },
    "color": {
      "field": "kind",
      "type": "nominal",
      "title": "File"
    },
    "tooltip": [
      {
        "field": "name",
        "type": "nominal"
      },
      {
        "field": "taken_at",
        "type": "temporal"
      }
    ]
  }
}
